import{z as i,x as s,o as e,c as l,q as t,j as r,D as E,d as B,s as n,S as A}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"动态合同","description":"","frontmatter":{"title":"动态合同","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ct-dynamic-contracts.md","filePath":"econ/ct-dynamic-contracts.md","lastUpdated":1791413859000}'),c={name:"econ/ct-dynamic-contracts.md"};function d(m,a,p,h,C,f){const o=s("Mermaid");return e(),l("div",null,[a[2]||(a[2]=t('<h1 id="动态合同" tabindex="-1">动态合同 <a class="header-anchor" href="#动态合同" aria-label="Permalink to &quot;动态合同&quot;">​</a></h1><div class="epigraph"><p>长期关系的全部要点是：今天的产出改变明天的租金；合同设计就是选择这条映射。</p><footer>—— 据 Spear and Srivastava, Review of Economic Studies, 1987；Laffont and Tirole, Review of Economic Studies, 1988 整理</footer></div><p><a href="/econ/ct-adverse-selection-deep">上一课</a>把连续类型的筛选机器装好，但合同仍是一次性的。现实里的保险、债务、规制合同都在时间中续写：今天的产出既是可验证的历史，也是明天重谈条款的筹码。本课把时间写进合同，处理三个一次性模型里不存在的问题：声誉能否替代显性激励、承诺的缺失怎样制造棘轮、再谈判怎样把长期合同拆短。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把前两课的规划原样重复 \\(T\\) 期并不够——难点不在重复，而在两条新约束。第一，未来支付的效率取决于过去的产出：好年景应当换来更宽松的明天，这条映射本身就是合同的内容，需要新的状态变量把它记下来。第二，委托人今天签的条款，明天会想改：看到代理人高成本后，重定目标是委托人的短期理性；预见到这一点，代理人今天就会藏拙。静态菜单是同时宣布的，不存在这个问题；时间一打开，承诺从背景假设变成设计对象。</p><h3 id="延续值作为状态" tabindex="-1">延续值作为状态 <a class="header-anchor" href="#延续值作为状态" aria-label="Permalink to &quot;延续值作为状态&quot;">​</a></h3><p>递归化是标准解法。把委托人向代理人承诺的延续效用 \\(v\\) 当作状态变量，合同在每期给两样东西：当期工资，与下一期的 \\(v&#39;\\)。Spear 与 Srivastava 在 1987 年证明，无限期重复道德风险的最优合同可以压成两条件：承诺保持 \\(v=\\mathbb{E}[u(w)+\\delta v&#39;]\\)，与跨期的激励差当期结清。好产出不再只涨奖金，而是抬高 \\(v&#39;\\)——把一部分回报存进未来，委托人用未来的租金买今天的努力，比一次性现金便宜，因为代理人厌恶风险而未来平滑。历史的全部作用都收进 \\(v\\)：记住 \\(v\\)，就不用记住完整的产出序列。</p><p><span class="marginnote">效率工资的保证金没有法律形态：工人无法预缴一笔押金，失业威胁只能靠贴现兑现。延续值就是把它写成状态——保证金可以欠着，但不能不记账；账一断，纪律就断。</span></p><p><span class="marginnote">数字实例：设 \\(v=100\\)、贴现因子 \\(\\delta=0.9\\)。代理人本期偷懒可换 10 个单位的省力，但一旦被发现，明天起延续值清零。10 对 100，偷懒不值——最优合同正是把「未来的账」算得足够大，让当期的诱惑输给折现后的租金。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>承诺强度分三档处理。完全承诺下，递归合同如上，当期信号权重仍由<a href="/econ/holmstrom-informativeness">充足统计</a>管，动态只改回报的期限结构。完全不可承诺但行动可观察时，退到<a href="/econ/folk-theorem">重复博弈与无名氏定理</a>的世界：惩罚必须自身是均衡，贴现要压过偏离增益；Radner 在 1981 年补上有限期——近似最优的 \\(\\varepsilon\\) 均衡把这条直觉延伸到有终点的合同。介于两者之间的是隐藏行动加声誉：质量溢价流做抵押，削质的短期节约对不上溢价的现值，声誉才立得住，<a href="/econ/quality-reputation-choosing">质量与声誉</a>那本抵押账原样适用。</p>',11)),(e(),r(A,null,{default:E(()=>[n(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E4%BB%8A%E5%A4%A9%E4%BA%A7%E5%87%BA%20x%22%5D%20--%3E%20PAY%5B%22%E5%BD%93%E6%9C%9F%E5%B7%A5%E8%B5%84%20w(x)%22%5D%0A%20%20X%20--%3E%20V%5B%22%E5%BB%B6%E7%BB%AD%E5%80%BC%20v%E2%80%B2%EF%BC%9A%E5%A5%BD%E4%BA%A7%E5%87%BA%E6%8A%AC%E9%AB%98%E6%98%8E%E5%A4%A9%22%5D%0A%20%20V%20--%3E%20STATE%5B%22%E7%8A%B6%E6%80%81%20v%20%E6%9B%B4%E6%96%B0%EF%BC%8C%E8%BF%9B%E5%85%A5%E4%B8%8B%E4%B8%80%E6%9C%9F%22%5D%0A%20%20STATE%20--%3E%20IC%5B%22%E8%B7%A8%E6%9C%9F%E6%BF%80%E5%8A%B1%E5%B7%AE%20%E2%89%A5%20%E5%BD%93%E6%9C%9F%E7%9C%81%E5%8A%9B%E6%94%B6%E7%9B%8A%22%5D%0A%20%20IC%20--%3E%20X%0A%20%20RENEG%5B%22%E5%A7%94%E6%89%98%E4%BA%BA%E6%83%B3%E9%87%8D%E8%B0%88%E6%9D%A1%E6%AC%BE%22%5D%20--%3E%20BREAK%5B%22%E6%89%BF%E8%AF%BA%E7%A0%B4%E8%A3%82%EF%BC%9A%E5%90%88%E5%90%8C%E6%8A%98%E6%88%90%E7%9F%AD%E4%B8%B2%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>动态逆向选择的新病是棘轮。规制者无法承诺不使用今天的成本实现：今年干得漂亮，明年的目标就按漂亮定，超额租金被抽走；预见到这条映射，高效率者第一年就装穷，动态筛选比静态筛选更堵。Laffont 与 Tirole 在 1988 年把这一点写全——信息泄露本身是租金的敌人，分离越快，未来抽租越狠，隐藏的动机越强。这与<a href="/econ/commitment-devices">承诺装置</a>同构：锁的是下一期的自己或对手的短期理性。</p><p><span class="marginnote">直觉类比：棘轮就是自行车脚踏板里那种「只能往前转、不能往后退」的卡齿，用在绩效指标上便是「能上不能下」。去年冲到 120%，今年基数就按 120% 定——所以懂行的人宁可去年只交 80%。指标越容易被历史重置，装穷的动机越强。</span></p><p><span class="marginnote">常见误区：初学者容易以为「信息越多筛选越准，所以显示越多越好」。动态模型恰好反过来：今天的显示会被明天的合同拿去用，分离本身就是租金的泄露。信息有价值的前提，是委托人能承诺不滥用它。</span></p>',4)),(e(),r(A,null,{default:E(()=>[n(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%AC%AC%E4%B8%80%E5%B9%B4%EF%BC%9A%E9%AB%98%E6%95%88%E7%8E%87%E8%80%85%E5%A6%82%E5%AE%9E%E6%98%BE%E7%A4%BA%E7%B1%BB%E5%9E%8B%22%5D%20--%3E%20B%5B%22%E8%A7%84%E5%88%B6%E8%80%85%E6%9B%B4%E6%96%B0%E6%88%90%E6%9C%AC%E4%BC%B0%E8%AE%A1%22%5D%0A%20%20B%20--%3E%20C%5B%22%E7%AC%AC%E4%BA%8C%E5%B9%B4%E7%9B%AE%E6%A0%87%E6%8C%89%E4%BD%8E%E6%88%90%E6%9C%AC%E8%AE%BE%E5%AE%9A%22%5D%0A%20%20C%20--%3E%20D%5B%22%E4%BF%A1%E6%81%AF%E7%A7%9F%E9%87%91%E8%A2%AB%E6%8A%BD%E8%B5%B0%22%5D%0A%20%20A2%5B%22%E7%AC%AC%E4%B8%80%E5%B9%B4%EF%BC%9A%E9%AB%98%E6%95%88%E7%8E%87%E8%80%85%E8%A3%85%E7%A9%B7%22%5D%20--%3E%20E%5B%22%E7%9B%AE%E6%A0%87%E6%97%A0%E6%B3%95%E6%94%B6%E7%B4%A7%22%5D%0A%20%20E%20--%3E%20F%5B%22%E5%AE%BD%E6%9D%BE%E7%9B%AE%E6%A0%87%E4%B8%8E%E7%A7%9F%E9%87%91%E4%BF%9D%E7%95%99%22%5D%0A%20%20D%20--%3E%20G%5B%22%E9%A2%84%E8%A7%81%20C%EF%BC%8C%E7%AC%AC%E4%B8%80%E5%B9%B4%E5%B0%B1%E9%80%89%20A2%EF%BC%9A%E7%AD%9B%E9%80%89%E6%9B%B4%E5%A0%B5%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>隐性激励是动态合同的另一个极端：完全不要显性合同。<a href="/econ/career-concerns">职业关注</a>课已写，市场用产出更新能力估计，早期推断最灵敏所以隐性激励最强；读进本课框架，是零显性激励、全额延续值的角点解——市场本身就是那本 \\(v\\) 账。债务合同则展示期限权衡：<a href="/econ/debt-maturity-rollover">滚动与期限</a>在纪律与再融资风险间取舍，<a href="/econ/debt-overhang">债务积压</a>是未来租金被截走后的投资萎缩，活期存款是以<a href="/econ/diamond-dybvig">挤兑</a>为坏均衡的动态合同。递归方法正是把它们统一处理的语法。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>最大的裂缝在再谈判。Hart 与 Moore 在 1988 年证明，若双方事前预期到事后必然重谈，长期合同的最优条款会被谈判逐段拆掉，承诺的收益蒸发——<a href="/econ/incomplete-contracts">不完全合同</a>课引过这一结果，本课程里它是动态合同的硬边界：没有承诺装置，写的越长失效越快。多委托人与合谋的时间积累留给下一课；有限记忆下的简化合同是仍在推进的文献。</p><p><span class="marginnote">术语翻译：再谈判就是「合同签了不算数，事后双方坐下来重新分蛋糕」。初学者容易以为合同写得越长越保险；实际上条款越长，事后想改的环节越多，只要每一环都预期到会被重谈，长期合同就被拆成一串短合同，承诺的好处也随之蒸发。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>动态合同的核心状态是延续值 \\(v\\)：承诺保持与跨期激励两条件压成递归。</li><li>好产出抬高明天而非今天，是用未来租金买当期努力，风险成本更低。</li><li>承诺不可得时，棘轮让代理人藏拙，信息泄露毁掉动态筛选。</li><li>无名氏定理、\\(\\varepsilon\\) 均衡与声誉溢价是无承诺三档的对应工具。</li><li>再谈判预期会把长期合同拆成短串，承诺装置因此是设计品而非假设。</li><li>出处：Radner, <em>Econometrica</em> 1981；Holmström, <em>RES</em> 1999；Spear and Srivastava, <em>REStud</em> 1987；Laffont and Tirole, <em>REStud</em> 1988；Hart and Moore, <em>Econometrica</em> 1988。</li></ul>',6))])}const u=i(c,[["render",d]]);export{D as __pageData,u as default};
